function getConditionIcon(description: string): React.ReactNode {
  const d = (description || '').toLowerCase();
  if (d.includes('thunder') || d.includes('lightning')) return <CloudLightning className="w-5 h-5 text-yellow-400" />;
  if (d.includes('rain') || d.includes('drizzle') || d.includes('shower')) return <CloudRain className="w-5 h-5 text-blue-400" />;
  if (d.includes('snow') || d.includes('ice')) return <Cloud className="w-5 h-5 text-blue-200" />;
  if (d.includes('cloud') || d.includes('overcast')) return <Cloud className="w-5 h-5 text-gray-300" />;
  if (d.includes('fog') || d.includes('mist')) return <Wind className="w-5 h-5 text-gray-400" />;
  return <Zap className="w-5 h-5 text-yellow-300" />;
}

