async def _safe_call_llm(*args, **kwargs):
    """LLM CALL ISOLATION MANDATE: wraps call_llm_async so a transient LLM failure (timeout, 503, decode error) never falls through to the outer route try/except and wipes the real upstream-API data. Returns {'text': ''} on any exception so callers' .get('text', fallback) yields their fallback string while real data still flows. NOTE: the helper body calls `_raw_call_llm_async` (a module-level alias of the original `call_llm_async`) so the global rewrite of `await call_llm_async(` → `await _safe_call_llm(` does NOT recurse into this helper."""
    try:
        return await _raw_call_llm_async(*args, **kwargs)
    except Exception:
        return {"text": ""}
